# app.rb
require 'sinatra'
require 'httparty'
require 'json'

class CurrencyApp < Sinatra::Base
  configure do
    set :public_folder, File.dirname(__FILE__) + '/public'
  end

  # API endpoint для отримання курсів валют
  API_URL = 'https://api.privatbank.ua/p24api/pubinfo?exchange&json&coursid=11'

