  get '/api/rates' do
    content_type :json
    get_exchange_rates.to_json
  end

  private

  def get_exchange_rates
    begin
      response = HTTParty.get(API_URL)

      if response.success?
        rates = JSON.parse(response.body)
        {
          success: true,
          rates: rates,
          timestamp: Time.now.strftime('%Y-%m-%d %H:%M:%S')
        }
      else
        {
          success: false,
          error: "Помилка отримання даних: #{response.code}",
          timestamp: Time.now.strftime('%Y-%m-%d %H:%M:%S')
        }
      end
    rescue StandardError => e
      {
        success: false,
        error: "Помилка: #{e.message}",
        timestamp: Time.now.strftime('%Y-%m-%d %H:%M:%S')
      }
    end
  end
end
