    <script>
        function loadRates() {
            const ratesList = document.getElementById('rates-list');
            const timestamp = document.getElementById('timestamp');
            const updateTime = document.getElementById('update-time');

            ratesList.innerHTML = '<div class="loading">Завантаження курсів валют...</div>';
            timestamp.textContent = 'Оновлення...';

            fetch('/api/rates')
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        displayRates(data.rates);
                        const time = new Date().toLocaleString('uk-UA');
                        timestamp.textContent = `Оновлено: ${time}`;
                        updateTime.textContent = time;
                    } else {
                        ratesList.innerHTML = `<div class="error">${data.error}</div>`;
                        timestamp.textContent = 'Помилка оновлення';
                    }
                })
                .catch(error => {
                    ratesList.innerHTML = `<div class="error">Помилка мережі: ${error.message}</div>`;
                    timestamp.textContent = 'Помилка оновлення';
                });
        }

        function displayRates(rates) {
            const ratesList = document.getElementById('rates-list');

            if (!rates || rates.length === 0) {
                ratesList.innerHTML = '<div class="error">Дані про курси валют відсутні</div>';
                return;
            }

            ratesList.innerHTML = rates.map(rate => `
                <div class="currency-card">
                    <div class="currency-header">
                        <span class="currency-name">${getCurrencyName(rate.ccy)}</span>
                        <span class="currency-code">${rate.ccy}</span>
