                        </div>
                        <div class="rate-item">
                            <div class="rate-label">Продаж</div>
                            <div class="rate-value">${parseFloat(rate.sale).toFixed(2)} ${rate.base_ccy}</div>
                        </div>
                    </div>
                </div>
            `).join('');
        }

        function getCurrencyName(code) {
            const names = {
                'USD': 'Долар США',
                'EUR': 'Євро',
                'BTC': 'Біткойн',
                'GBP': 'Фунт стерлінгів',
                'PLN': 'Польський злотий'
            };
            return names[code] || code;
        }

        // Завантажити курси при завантаженні сторінки
        document.addEventListener('DOMContentLoaded', loadRates);

        // Автоматичне оновлення кожні 5 хвилин
        setInterval(loadRates, 300000);
    </script>
