## Основна програма (app.rb)

```ruby
# app.rb
require 'sinatra'
require 'httparty'
require 'json'
require 'dotenv'
Dotenv.load

class NovaPoshtaService
  API_URL = 'https://api.novaposhta.ua/v2.0/json/'.freeze

  def self.find_post_offices(city_name, address = nil, limit = 20)
    request_payload = {
      apiKey: ENV['NOVA_POSHTA_API_KEY'],
      modelName: 'Address',
      calledMethod: 'getWarehouses',
      methodProperties: {
        CityName: city_name,
        Limit: limit
      }
    }

    response = HTTParty.post(API_URL, body: request_payload.to_json, headers: { 'Content-Type' => 'application/json' })

    if response.success?
      offices = JSON.parse(response.body)['data'] || []

      # Якщо задано адресу, фільтруємо результати
      if address
        offices.select! { |office| office['Description'].downcase.include?(address.downcase) }
      end

      offices
    else
      []
    end
  end
end

class GeocodingService
  def self.geocode_address(address)
    # Використовуємо Nominatim (OpenStreetMap) для геокодування
    encoded_address = URI.encode_www_form_component(address)
    url = "https://nominatim.openstreetmap.org/search?q=#{encoded_address}&format=json&limit=1"

    response = HTTParty.get(url, headers: { 'User-Agent' => 'NovaPoshtaMapApp/1.0' })

    if response.success? && !JSON.parse(response.body).empty?
      result = JSON.parse(response.body).first
      {
        lat: result['lat'].to_f,
        lon: result['lon'].to_f,
        display_name: result['display_name']
      }
    else
      nil
    end
  end
end

# Маршрути Sinatra
get '/' do
  erb :index
end

post '/search' do
  address = params[:address]

  if address.nil? || address.empty?
    return { error: 'Будь ласка, введіть адресу' }.to_json
  end

  # Геокодуємо адресу
  location = GeocodingService.geocode_address(address)

  if location.nil?
    return { error: 'Не вдалося знайти вказану адресу' }.to_json
  end

  # Шукаємо поштомати в місті
  city = location[:display_name].split(',').find { |part| part.match(/місто|село|селище/) } || location[:display_name].split(',').first
  offices = NovaPoshtaService.find_post_offices(city.strip, address)

  {
    location: location,
    offices: offices,
    city: city.strip
  }.to_json
end

# Запуск сервера
if __FILE__ == $0
  set :port, 4567
  set :bind, '0.0.0.0'
end
```

