<body>
    <div class="container">
        <h1>Поштомати Нової Пошти</h1>

        <div class="search-form">
            <input type="text" id="addressInput" class="search-input" placeholder="Введіть адресу (наприклад: Київ, Хрещатик 1)">
            <button onclick="searchPostOffices()" class="search-button">Знайти поштомати</button>
        </div>

        <div id="errorMessage" class="error" style="display: none;"></div>

        <div id="map"></div>

        <div id="officeList" class="office-list"></div>
    </div>

    <script src="https://unpkg.com/leaflet@1.7.1/dist/leaflet.js"></script>
    <script>
        let map = L.map('map').setView([50.4501, 30.5234], 10); // Київ за замовчуванням
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors'
        }).addTo(map);

        let markers = [];
        let officeMarkers = [];

        function searchPostOffices() {
            const address = document.getElementById('addressInput').value.trim();
            const errorDiv = document.getElementById('errorMessage');

            if (!address) {
                showError('Будь ласка, введіть адресу');
                return;
            }

            errorDiv.style.display = 'none';

            fetch('/search', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: 'address=' + encodeURIComponent(address)
            })
            .then(response => response.json())
            .then(data => {
                if (data.error) {
                    showError(data.error);
                    return;
                }

                displayResults(data);
            })
            .catch(error => {
                console.error('Error:', error);
                showError('Сталася помилка при пошуку');
            });
        }

        function displayResults(data) {
            // Очищаємо попередні маркери
            clearMarkers();

            const location = data.location;
            const offices = data.offices;
            const officeList = document.getElementById('officeList');

            // Центруємо мапу на введеній адресі
            map.setView([location.lat, location.lon], 14);

            // Додаємо маркер для введеної адреси
            const addressMarker = L.marker([location.lat, location.lon])
                .addTo(map)
                .bindPopup('<b>Ваша адреса</b><br>' + location.display_name);
            markers.push(addressMarker);

            // Додаємо маркери для поштоматів
            offices.forEach(office => {
                if (office['Latitude'] && office['Longitude']) {
                    const officeMarker = L.marker([parseFloat(office['Latitude']), parseFloat(office['Longitude'])])
                        .addTo(map)
                        .bindPopup(`
                            <b>${office['Description']}</b><br>
                            ${office['CityDescription']}<br>
                            ${office['Phone'] || 'Телефон не вказано'}
                        `);

                    officeMarkers.push({
                        marker: officeMarker,
                        office: office
                    });

                    // Додаємо обробник кліку на маркер
                    officeMarker.on('click', function() {
                        highlightOffice(office);
                    });
                }
            });

            // Показуємо список поштоматів
            officeList.innerHTML = '';
            if (offices.length === 0) {
                officeList.innerHTML = '<p>Поштоматів не знайдено поблизу вказаної адреси</p>';
            } else {
                offices.forEach(office => {
                    const officeItem = document.createElement('div');
                    officeItem.className = 'office-item';
                    officeItem.innerHTML = `
                        <h4>${office['Description']}</h4>
                        <p><strong>Адреса:</strong> ${office['CityDescription']}, ${office['ShortAddress']}</p>
                        <p><strong>Графік роботи:</strong> ${office['Schedule'] || 'Не вказано'}</p>
                        ${office['Phone'] ? `<p><strong>Телефон:</strong> ${office['Phone']}</p>` : ''}
                    `;
                    officeItem.onclick = () => {
                        if (office['Latitude'] && office['Longitude']) {
                            map.setView([parseFloat(office['Latitude']), parseFloat(office['Longitude'])], 16);
                            highlightOffice(office);
                        }
                    };
                    officeList.appendChild(officeItem);
                });
            }
        }

        function highlightOffice(office) {
            // Знаходимо маркер для цього поштомату і відкриваємо popup
            const officeMarker = officeMarkers.find(om => om.office['Number'] === office['Number']);
            if (officeMarker) {
                officeMarker.marker.openPopup();
            }
        }

        function clearMarkers() {
            markers.forEach(marker => map.removeLayer(marker));
            officeMarkers.forEach(om => map.removeLayer(om.marker));
            markers = [];
            officeMarkers = [];
        }

        function showError(message) {
            const errorDiv = document.getElementById('errorMessage');
            errorDiv.textContent = message;
            errorDiv.style.display = 'block';
        }

        // Дозволяємо пошук по натисканню Enter
        document.getElementById('addressInput').addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                searchPostOffices();
            }
        });
    </script>
</body>
</html>
