## Контролер для підписок

### app/controllers/push_subscriptions_controller.rb

```ruby
class PushSubscriptionsController < ApplicationController
  skip_before_action :verify_authenticity_token, only: [:create]
  before_action :authenticate_user!, except: [:create]

  def create
    subscription_params = params.require(:subscription).permit(:endpoint, keys: [:p256dh, :auth])

    # Спробуємо знайти існуючу підписку або створити нову
    subscription = PushSubscription.find_by(endpoint: subscription_params[:endpoint])

    if subscription
      subscription.update(keys: subscription_params[:keys])
    else
      subscription = PushSubscription.create_from_params(subscription_params, current_user)
    end

    if subscription.persisted?
      render json: { status: 'success' }, status: :created
    else
      render json: { errors: subscription.errors.full_messages }, status: :unprocessable_entity
    end
  end

  def destroy
    subscription = PushSubscription.find_by(id: params[:id], user: current_user)

    if subscription&.destroy
      render json: { status: 'success' }
    else
      render json: { errors: ['Підписку не знайдено'] }, status: :not_found
    end
  end
end
```

## Сервіс для відправки сповіщень

### app/services/webpush_service.rb

```ruby
class WebpushService
  def self.send_notification(subscription, title, body, url = nil)
    message = {
      title: title,
      body: body,
      icon: '/icon-192x192.png',
      badge: '/badge-72x72.png',
      url: url || Rails.application.routes.url_helpers.root_url
    }.to_json

    begin
      response = Webpush.payload_send(
        message: message,
        endpoint: subscription.endpoint,
        p256dh: subscription.p256dh,
        auth: subscription.auth,
        vapid: {
          subject: "mailto:admin@yourdomain.com",
          public_key: Rails.application.credentials.vapid.public_key,
          private_key: Rails.application.credentials.vapid.private_key
        },
        ttl: 24 * 60 * 60 # 24 години
      )

      Rails.logger.info "WebPush відправлено: #{response&.code}"
      true
    rescue Webpush::InvalidSubscription => e
      Rails.logger.error "Невірна підписка: #{e.message}"
      subscription.destroy
      false
    rescue StandardError => e
      Rails.logger.error "Помилка WebPush: #{e.message}"
      false
    end
  end

  def self.broadcast_notification(title, body, url = nil)
    PushSubscription.find_each do |subscription|
      send_notification(subscription, title, body, url)
    end
  end

  def self.notify_user(user, title, body, url = nil)
    user.push_subscriptions.each do |subscription|
      send_notification(subscription, title, body, url)
    end
  end
end
```

