### ofac_checker.rb

```ruby
require 'httparty'
require 'active_model'

class OFACChecker
  include ActiveModel::Validations

  OFAC_API_URL = "https://api.trade.gov/gateway/v1/consolidated_screening_list/search"
  API_KEY = ENV['OFAC_API_KEY'] # Отримати ключ з https://api.trade.gov/

  attr_accessor :first_name, :last_name, :date_of_birth, :country

  validates :first_name, :last_name, presence: true

  def initialize(attributes = {})
    attributes.each do |key, value|
      send("#{key}=", value)
    end
  end

  def check_sanctions
    return false unless valid?

    response = HTTParty.get(OFAC_API_URL, query: build_query)

    if response.success?
      parse_response(response)
    else
      Rails.logger.error "OFAC API Error: #{response.code} - #{response.body}"
      false
    end
  rescue StandardError => e
    Rails.logger.error "OFAC Check Error: #{e.message}"
    false
  end

  private

  def build_query
    {
      name: "#{first_name} #{last_name}",
      countries: country,
      api_key: API_KEY,
      size: 10,
      offset: 0
    }.compact
  end

  def parse_response(response)
    data = JSON.parse(response.body)

    if data['results'] && data['results'].any?
      matches = data['results'].select do |entry|
        match_probability(entry)
      end

      matches.any?
    else
      false
    end
  end

  def match_probability(entry)
    # Базова перевірка співпадіння імені
    entry_name = entry['name']&.downcase || ''
    search_name = "#{first_name} #{last_name}".downcase

    # Перевірка співпадіння країни, якщо вказана
    country_match = country.blank? || 
                   entry['addresses']&.any? { |addr| addr['country']&.downcase == country.downcase }

    # Перевірка дати народження, якщо вказана
    dob_match = date_of_birth.blank? || 
               entry['dates_of_birth']&.any? { |dob| dob == date_of_birth.to_s }

    name_similarity = calculate_similarity(entry_name, search_name)

    # Вважаємо збігом, якщо схожість імені > 80% та є співпадіння по іншим критеріям
    name_similarity > 0.8 && country_match && dob_match
  end

  def calculate_similarity(str1, str2)
    # Простий алгоритм схожості (можна використати gem 'amatch' для кращих результатів)
    str1 = str1.downcase.gsub(/[^a-zа-яїієґ0-9]/, '')
    str2 = str2.downcase.gsub(/[^a-zа-яїієґ0-9]/, '')

    return 1.0 if str1 == str2

    # Алгоритм Левенштейна для визначення відстані
    distance = levenshtein_distance(str1, str2)
    max_length = [str1.length, str2.length].max.to_f

    1.0 - (distance / max_length)
  end

  def levenshtein_distance(str1, str2)
    n = str1.length
    m = str2.length
    return m if n == 0
    return n if m == 0

    d = Array.new(n + 1) { Array.new(m + 1) }

    (0..n).each { |i| d[i][0] = i }
    (0..m).each { |j| d[0][j] = j }

    (1..n).each do |i|
      (1..m).each do |j|
        cost = str1[i - 1] == str2[j - 1] ? 0 : 1
        d[i][j] = [
          d[i - 1][j] + 1,     # deletion
          d[i][j - 1] + 1,     # insertion
          d[i - 1][j - 1] + cost # substitution
        ].min
      end
    end

    d[n][m]
  end
end
```

### Модель користувача з перевіркою OFAC

#### user.rb

```ruby
class User < ApplicationRecord
  include ActiveModel::Validations

  validates :first_name, :last_name, presence: true
  validate :check_ofac_sanctions, on: :create

  before_create :perform_ofac_check

  attr_accessor :skip_ofac_check

  private

  def check_ofac_sanctions
    return if skip_ofac_check

    checker = OFACChecker.new(
      first_name: first_name,
      last_name: last_name,
      date_of_birth: date_of_birth,
      country: country
    )

    if checker.check_sanctions
      errors.add(:base, 'Користувач знайдений у санкційних списках OFAC. Реєстрація неможлива.')
    end
  end

  def perform_ofac_check
    return if skip_ofac_check

    checker = OFACChecker.new(
      first_name: first_name,
      last_name: last_name,
      date_of_birth: date_of_birth,
      country: country
    )

    if checker.check_sanctions
      throw :abort
    end
  end
end
```

