```javascript
document.addEventListener('DOMContentLoaded', function() {
  const ofacForm = document.getElementById('user-form');

  if (ofacForm) {
    const firstNameInput = document.getElementById('user_first_name');
    const lastNameInput = document.getElementById('user_last_name');
    const dobInput = document.getElementById('user_date_of_birth');
    const countryInput = document.getElementById('user_country');

    const checkOFAC = debounce(function() {
      if (firstNameInput.value && lastNameInput.value) {
        fetch('/check_ofac', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': document.querySelector('[name="csrf-token"]').content
          },
          body: JSON.stringify({
            first_name: firstNameInput.value,
            last_name: lastNameInput.value,
            date_of_birth: dobInput.value,
            country: countryInput.value
          })
        })
        .then(response => response.json())
        .then(data => {
          if (data.sanctioned) {
            showOFACWarning(data.message);
          } else {
            hideOFACWarning();
          }
        });
      }
    }, 500);

    [firstNameInput, lastNameInput, dobInput, countryInput].forEach(input => {
      input.addEventListener('input', checkOFAC);
    });
  }

  function showOFACWarning(message) {
    let warning = document.getElementById('ofac-warning');
    if (!warning) {
      warning = document.createElement('div');
      warning.id = 'ofac-warning';
      warning.className = 'alert alert-danger';
      document.querySelector('form').prepend(warning);
    }
    warning.textContent = message;
  }

  function hideOFACWarning() {
    const warning = document.getElementById('ofac-warning');
    if (warning) {
      warning.remove();
    }
  }

  function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
      const later = () => {
        clearTimeout(timeout);
        func(...args);
      };
      clearTimeout(timeout);
      timeout = setTimeout(later, wait);
    };
  }
});
