**Implementation**
```ruby
require 'nokogiri'
require 'date'

# Define a class to represent a payment
class Payment
  attr_accessor :supplier_name, :supplier_iban, :amount, :currency, :reference

  def initialize(supplier_name, supplier_iban, amount, currency, reference)
    @supplier_name = supplier_name
    @supplier_iban = supplier_iban
    @amount = amount
    @currency = currency
    @reference = reference
  end
end

# Define a class to generate the SEPA credit transfer XML file
class SepaCreditTransferGenerator
  def initialize(payments, creditor_name, creditor_iban, creditor_bic)
    @payments = payments
    @creditor_name = creditor_name
    @creditor_iban = creditor_iban
    @creditor_bic = creditor_bic
  end

  def generate_xml
    builder = Nokogiri::XML::Builder.new do |xml|
      xml.CstmrCdtTrfInitn {
        xml.GrpHdr {
          xml.MsgId { xml.text 'PAY' + Time.now.strftime('%Y%m%d%H%M%S') }
          xml.CreDtTm { xml.text Time.now.strftime('%Y-%m-%dT%H:%M:%S') }
          xml.InitgPty {
            xml.Nm { xml.text @creditor_name }
            xml.Id {
              xml.OrgId {
                xml.Othr {
                  xml.Id { xml.text @creditor_iban }
                  xml.SchmeNm {
                    xml.Cd { xml.text 'IBAN' }
                  }
                }
              }
            }
          }
        }
        xml.PmtInf {
          xml.PmtInfId { xml.text 'PAY' + Time.now.strftime('%Y%m%d%H%M%S') }
          xml.PmtMtd { xml.text 'TRF' }
          xml.BtchBookg { xml.text 'true' }
          xml.NbOfTxs { xml.text @payments.size.to_s }
          xml.CtrlSum { xml.text @payments.map(&:amount).sum.to_s }
          xml.PmtTpInf {
            xml.SvcLvl {
              xml.Cd { xml.text 'SEPA' }
            }
            xml.LclInstrm {
              xml.Cd { xml.text 'CORE' }
            }
            xml.CtgyPurp {
              xml.Cd { xml.text 'SALA' }
            }
          }
          xml.ReqExctnDt { xml.text Date.today.strftime('%Y-%m-%d') }
          xml.Dbtr {
            xml.Nm { xml.text @creditor_name }
            xml.Id {
              xml.OrgId {
                xml.Othr {
                  xml.Id { xml.text @creditor_iban }
                  xml.SchmeNm {
                    xml.Cd { xml.text 'IBAN' }
                  }
                }
              }
            }
          }
          xml.DbtrAcct {
            xml.Id {
              xml.IBAN { xml.text @creditor_iban }
            }
          }
          xml.DbtrAgt {
            xml.FinInstnId {
              xml.BIC { xml.text @creditor_bic }
            }
          }
          @payments.each do |payment|
            xml.CdtTrfTxInf {
              xml.PmtId {
                xml.InstrId { xml.text payment.reference }
                xml.EndToEndId { xml.text payment.reference }
              }
              xml.Amt {
                xml.InstdAmt {
                  xml.Ccy { xml.text payment.currency }
                  xml.value { xml.text payment.amount.to_s }
                }
              }
              xml.CdtrAgt {
                xml.FinInstnId {
                  xml.BIC { xml.text '' } # Not required for SEPA
                }
              }
              xml.Cdtr {
                xml.Nm { xml.text payment.supplier_name }
                xml.Id {
                  xml.OrgId {
                    xml.Othr {
                      xml.Id { xml.text payment.supplier_iban }
                      xml.SchmeNm {
                        xml.Cd { xml.text 'IBAN' }
                      }
                    }
                  }
                }
              }
              xml.CdtrAcct {
                xml.Id {
                  xml.IBAN { xml.text payment.supplier_iban }
                }
              }
            }
          end
        }
      }
    end
