            'City' => 'Recipient City',
            'StateCode' => 'Recipient State Code',
            'PostalCode' => 'Recipient Postal Code',
            'CountryCode' => 'US'
          }
        },
        'ShipFrom' => {
          'Name' => 'Your Company Name',
