              'UnitOfMeasurement' => {
                'Code' => 'IN'
              },
              'Length' => length,
              'Width' => width,
              'Height' => height
            },
            'PackageWeight' => {
              'UnitOfMeasurement' => {
                'Code' => 'LBS'
              },
              'Weight' => weight
            }
          }
        }
      }
    }

    response = client.call(:process_rate, message: request)

    # Parse the response
    rates = []
    response.body[:rate_response][:rated_shipment].each do |shipment|
      rates << {
        service: shipment[:service][:code],
        rate: shipment[:total_charges][:monetary_value]
      }
    end

    rates
  end
end

