class FedExShipment
  def initialize(credentials)
    @credentials = credentials
    @client = Savon.client(
      wsdl: "https://wsbeta.fedex.com:443/web-services/ship?wsdl",
      basic_auth: [
        @credentials[:account_number],
        @credentials[:meter_number],
        @credentials[:key],
        @credentials[:password]
      ],
      ssl_verify_mode: :none
    )
  end

  def create_shipment(shipment_data)
    response = @client.call(:process_shipment, message: shipment_data)
    if response.success?
      tracking_number = response.body[:process_shipment_response][:completed_shipment_detail][:shipment_tracking_number]
      label = response.body[:process_shipment_response][:completed_shipment_detail][:label][:parts][:label_part]
      pdf_label = Base64.decode64(label[:content])
      return tracking_number, pdf_label
    else
      raise "Failed to create shipment: #{response.body[:fault][:fault_string]}"
    end
  end
end

