# fcm_notification.rb

require "firebase/cloud_messaging"
require "json"

class FCMNotification
  def initialize(api_key)
    @api_key = api_key
    @fcm = Firebase::CloudMessaging.new(api_key: @api_key)
  end

  # Send notification to Android devices
  def send_to_android(device_token, title, message)
    notification = {
      title: title,
      body: message,
      android: {
        priority: "HIGH",
        notification: {
          title: title,
          body: message
        }
      }
    }

    send_notification(device_token, notification)
  end

  # Send notification to iOS devices
  def send_to_ios(device_token, title, message)
    notification = {
      apns: {
        headers: {
          "apns-priority" => "5"
        },
        payload: {
          aps: {
            alert: {
              title: title,
              body: message
            },
            sound: "default"
          }
        }
      }
    }

    send_notification(device_token, notification)
  end

  private

  def send_notification(device_token, notification)
    response = @fcm.send(
      to: device_token,
      data: notification
    )

    if response.success?
      puts "Notification sent successfully to #{device_token}"
    else
      puts "Error sending notification to #{device_token}: #{response.error_message}"
    end
  end
end

