# SEPA Credit Transfer Generator (pain.001)

Here's a complete solution for generating SEPA credit transfer XML files in Ruby.

## Gemfile

```ruby
source 'https://rubygems.org'

gem 'nokogiri'
gem 'builder'
gem 'active_support'
gem 'zeitwerk'
```

## Implementation

```ruby
# lib/sepa_credit_transfer.rb
require 'builder'
require 'active_support'
require 'active_support/core_ext/string'
require 'active_support/core_ext/date_time'

class SepaCreditTransfer
  VERSION = '0.1.0'

  def initialize(creditor_info, batch_info, payments)
    @creditor_info = creditor_info
    @batch_info = batch_info
    @payments = payments
    @xml_builder = Builder::XmlMarkup.new(indent: 2)
  end

  def generate_xml
    @xml_builder.instruct!
    @xml_builder.tag!('Document', 'xmlns' => 'urn:iso:std:iso:20022:tech:xsd:pain.001.001.03',
                       'xmlns:xsi' => 'http://www.w3.org/2001/XMLSchema-instance') do
      @xml_builder.tag!('CstmrCdtTrfInitn') do
        # GrpHdr
        @xml_builder.tag!('GrpHdr') do
          @xml_builder.tag!('MsgId', generate_message_id)
          @xml_builder.tag!('CreDtTm', Time.current.iso8601)
          @xml_builder.tag!('NbOfTxs', @payments.length)
          @xml_builder.tag!('CtrlSum', total_amount)
          @xml_builder.tag!('InitgPty') do
            @xml_builder.tag!('Nm', @creditor_info[:name])
          end
        end

        # PmtInf
        @xml_builder.tag!('PmtInf') do
          @xml_builder.tag!('PmtInfId', @batch_info[:id])
          @xml_builder.tag!('PmtMtd', 'TRF')
          @xml_builder.tag!('BtchBookg', 'false')
          @xml_builder.tag!('NbOfTxs', @payments.length)
          @xml_builder.tag!('CtrlSum', total_amount)
          @xml_builder.tag!('PmtTpInf') do
            @xml_builder.tag!('SvcLvl') do
              @xml_builder.tag!('Cd', 'SEPA')
            end
            @xml_builder.tag!('LclInstrm') do
              @xml_builder.tag!('Cd', 'CORE')
            end
          end

          @xml_builder.tag!('ReqdExctnDt', @batch_info[:execution_date].strftime('%Y-%m-%d'))

          # Creditor
          @xml_builder.tag!('Dbtr') do
            @xml_builder.tag!('Nm', @creditor_info[:name])
            @xml_builder.tag!('PstlAdr') do
              @xml_builder.tag!('AdrLine', @creditor_info[:address_line1]) if @creditor_info[:address_line1]
              @xml_builder.tag!('AdrLine', @creditor_info[:address_line2]) if @creditor_info[:address_line2]
              @xml_builder.tag!('Ctry', @creditor_info[:country]) if @creditor_info[:country]
            end
          end

          @xml_builder.tag!('DbtrAcct') do
            @xml_builder.tag!('Id') do
              @xml_builder.tag!('IBAN', @creditor_info[:iban])
            end
            @xml_builder.tag!('Ccy', @creditor_info[:currency])
          end

          @xml_builder.tag!('DbtrAgt') do
            @xml_builder.tag!('FinInstnId') do
              @xml_builder.tag!('BIC', @creditor_info[:bic])
            end
          end

          # Payments
          @payments.each do |payment|
            @xml_builder.tag!('CdtTrfTxInf') do
              @xml_builder.tag!('PmtId') do
                @xml_builder.tag!('EndToEndId', payment[:end_to_end_id])
              end

              @xml_builder.tag!('Amt') do
                @xml_builder.tag!('InstdAmt', format_amount(payment[:amount]), 'Ccy' => payment[:currency])
              end

              @xml_builder.tag!('CdtrAgt') do
                @xml_builder.tag!('FinInstnId') do
                  @xml_builder.tag!('BIC', payment[:beneficiary_bic])
                end
              end

              @xml_builder.tag!('Cdtr') do
                @xml_builder.tag!('Nm', payment[:beneficiary_name])
                @xml_builder.tag!('PstlAdr') do
                  @xml_builder.tag!('AdrLine', payment[:beneficiary_address_line1]) if payment[:beneficiary_address_line1]
                  @xml_builder.tag!('AdrLine', payment[:beneficiary_address_line2]) if payment[:beneficiary_address_line2]
                  @xml_builder.tag!('Ctry', payment[:beneficiary_country]) if payment[:beneficiary_country]
                end
              end

              @xml_builder.tag!('CdtrAcct') do
                @xml_builder.tag!('Id') do
                  @xml_builder.tag!('IBAN', payment[:beneficiary_iban])
                end
              end

              @xml_builder.tag!('RmtInf') do
                @xml_builder.tag!('Ustrd', payment[:reference])
              end
            end
          end
        end
      end
    end
  end

  private

  def generate_message_id
    # Generate a unique message ID based on timestamp and random number
    timestamp = Time.current.strftime('%Y%m%d%H%M%S')
    random = rand(100000..999999)
    "MSG-#{timestamp}-#{random}"
  end

  def total_amount
    @payments.sum { |p| p[:amount] }.round(2)
  end

  def format_amount(amount)
    format('%.2f', amount)
  end
end

# Usage example
if __FILE__ == $0
  # Example usage
  creditor_info = {
    name: "Your Company Name",
    iban: "DE44500105170447890123",
    bic: "COBADEFFXXX",
    currency: "EUR",
    address_line1: "Main Street 123",
    address_line2: "12345 City",
    country: "DE"
  }

  batch_info = {
    id: "BATCH-20230615-001",
    execution_date: Date.today + 1 # Tomorrow
  }

  payments = [
    {
      end_to_end_id: "INV-2023-001",
      amount: 1500.00,
      currency: "EUR",
