Here's a complete Ruby solution for validating IBAN and BIC numbers with a Gemfile and implementation:

```ruby
# Gemfile
source 'https://rubygems.org'

gem 'sinatra'
gem 'sinatra-contrib'
gem 'iban-tools'
gem 'bic'
gem 'json'
gem 'erb'

# app.rb
require 'sinatra'
require 'sinatra/reloader' if development?
require 'iban-tools'
require 'bic'
require 'json'

enable :sessions

# Helper method to validate IBAN
def validate_iban(iban)
  return { valid: false, error: "IBAN cannot be empty" } if iban.nil? || iban.strip.empty?

  begin
    iban = iban.upcase.strip
    IBANTools::IBAN.new(iban)
    { valid: true }
  rescue IBANTools::InvalidFormat
    { valid: false, error: "Invalid IBAN format" }
  rescue IBANTools::InvalidChecksum
    { valid: false, error: "Invalid IBAN checksum" }
  rescue => e
    { valid: false, error: "IBAN validation error: #{e.message}" }
  end
end

# Helper method to validate BIC
def validate_bic(bic)
  return { valid: false, error: "BIC cannot be empty" } if bic.nil? || bic.strip.empty?

  begin
    bic = bic.upcase.strip
    BIC::BankIdentifierCode.new(bic)
    { valid: true }
  rescue BIC::InvalidFormat
    { valid: false, error: "Invalid BIC format" }
  rescue => e
    { valid: false, error: "BIC validation error: #{e.message}" }
  end
end

# Home page with form
get '/' do
  erb :index
end

# Handle form submission
post '/validate' do
  iban = params[:iban]
  bic = params[:bic]

  iban_result = validate_iban(iban)
  bic_result = validate_bic(bic)

  # Clear session messages
  session[:iban_error] = nil
  session[:bic_error] = nil
  session[:iban_valid] = nil
  session[:bic_valid] = nil

  # Store validation results in session for display
  if iban_result[:valid]
    session[:iban_valid] = true
  else
    session[:iban_error] = iban_result[:error]
  end

  if bic_result[:valid]
    session[:bic_valid] = true
  else
    session[:bic_error] = bic_result[:error]
  end

  # Redirect to results page
  redirect '/results'
end

# Results page
get '/results' do
  erb :results
end

# API endpoint for AJAX validation (optional)
get '/validate.json' do
  content_type :json

  iban = params[:iban]
  bic = params[:bic]

  iban_result = validate_iban(iban)
  bic_result = validate_bic(bic)

  result = {
    iban: {
      valid: iban_result[:valid],
      error: iban_result[:error]
    },
    bic: {
      valid: bic_result[:valid],
      error: bic_result[:error]
    }
  }

  result.to_json
end
```

