## app.rb
```ruby
require 'sinatra'
require 'coinbase-commerce'
require 'json'
require 'dotenv/load'
require 'active_record'
require 'sqlite3'
require 'bcrypt'

# Configure Coinbase Commerce
CoinbaseCommerce.configure do |config|
  config.api_key = ENV['COINBASE_API_KEY']
  config.api_version = '2018-03-22'
end

# Database configuration
ActiveRecord::Base.establish_connection(
  adapter: 'sqlite3',
  database: 'orders.db'
)

# Order model
class Order < ActiveRecord::Base
  validates :order_id, presence: true, uniqueness: true
  validates :amount, presence: true
  validates :currency, presence: true
  validates :status, presence: true

  def self.create_order(order_id, amount, currency, description = '')
    create!(
      order_id: order_id,
      amount: amount,
      currency: currency,
      status: 'pending',
      description: description,
      created_at: Time.now
    )
  end

  def mark_as_paid
    update(status: 'paid', paid_at: Time.now)
  end

  def mark_as_expired
    update(status: 'expired')
  end
end

# Create orders table if it doesn't exist
ActiveRecord::Schema.define do
  unless ActiveRecord::Base.connection.table_exists?(:orders)
    create_table :orders do |t|
      t.string :order_id, null: false
      t.decimal :amount, precision: 10, scale: 2, null: false
      t.string :currency, null: false
      t.string :status, null: false
      t.text :description
      t.datetime :paid_at
      t.datetime :created_at
      t.datetime :updated_at
    end

    add_index :orders, :order_id, unique: true
  end
end

# Helper methods
def generate_order_id
  "order_#{Time.now.to_i}_#{rand(1000..9999)}"
end

def get_base_url
  ENV['BASE_URL'] || "http://localhost:4567"
end

# Routes
get '/' do
  erb :index
end

post '/create-order' do
  content_type :json

  begin
    # Get parameters
    amount = params[:amount].to_f
    currency = params[:currency] || 'USD'
    description = params[:description] || 'Bitcoin Payment'

    # Validate input
    if amount <= 0
      return { error: 'Amount must be greater than 0' }.to_json
    end

    # Generate order ID
    order_id = generate_order_id

    # Create order in database
    order = Order.create_order(order_id, amount, currency, description)

    # Create Coinbase Commerce charge
    charge = CoinbaseCommerce::Charge.create(
      name: "Order #{order_id}",
      description: description,
      local_price: {
        amount: amount.to_s,
        currency: currency
      },
      pricing_type: 'fixed_price',
      redirect_url: "#{get_base_url}/success?order_id=#{order_id}",
      cancel_url: "#{get_base_url}/cancel?order_id=#{order_id}"
    )

    # Update order with charge information
    order.update(charge_id: charge.id, checkout_url: charge.checkout_url)

    # Return success response
    {
      order_id: order_id,
      charge_id: charge.id,
      checkout_url: charge.checkout_url,
      amount: amount,
      currency: currency
    }.to_json

  rescue => e
    puts "Error creating order: #{e.message}"
    status 500
    { error: 'Failed to create order' }.to_json
  end
end

get '/order/:order_id' do
  content_type :json

  order_id = params[:order_id]
  order = Order.find_by(order_id: order_id)

  if order
    {
      order_id: order.order_id,
      amount: order.amount,
      currency: order.currency,
      status: order.status,
      created_at: order.created_at
    }.to_json
  else
    status 404
    { error: 'Order not found' }.to_json
  end
end

# Webhook endpoint for Coinbase Commerce
post '/webhook' do
  content_type :json

  begin
    # Get the raw body and signature
    payload = request.body.read
    signature = request.env['HTTP_X_CC_WEBHOOK_SIGNATURE']

    # Verify webhook signature
    begin
      CoinbaseCommerce::Webhook.verify_signature(payload, signature, ENV['COINBASE_WEBHOOK_SECRET'])
    rescue CoinbaseCommerce::Webhook::InvalidSignature
      status 401
      return { error: 'Invalid signature' }.to_json
    end

    # Parse the webhook event
    event = JSON.parse(payload)

    # Process different event types
    case event['event']['type']
    when 'charge:confirmed'
      process_charge_confirmed(event)
    when 'charge:failed'
      process_charge_failed(event)
    when 'charge:expired'
      process_charge_expired(event)
    else
      # Ignore other events
      puts "Unhandled event type: #{event['event']['type']}"
    end

    # Return success response
    { status: 'ok' }.to_json

  rescue => e
    puts "Webhook processing error: #{e.message}"
    status 500
    { error: 'Webhook processing failed' }.to_json
  end
end

def process_charge_confirmed(event)
  charge_id = event['event']['data']['id']
  order = Order.find_by(charge_id: charge_id)

  if order
    puts "Marking order #{order.order_id} as paid"
    order.mark_as_paid
    puts "Order #{order.order_id} marked as paid successfully"
  else
    puts "Order not found for charge_id: #{charge_id}"
  end
end

def process_charge_failed(event)
  charge_id = event['event']['data']['id']
  order = Order.find_by(charge_id: charge_id)

  if order
    puts "Order #{order.order_id} failed"
    # You might want to update the status to failed here
    puts "Order #{order.order_id} marked as failed"
  else
    puts "Order not found for charge_id: #{charge_id}"
  end
end

def process_charge_expired(event)
  charge_id = event['event']['data']['id']
  order = Order.find_by(charge_id: charge_id)

  if order
    puts "Order #{order.order_id} expired"
    order.mark_as_expired
    puts "Order #{order.order_id} marked as expired"
  else
    puts "Order not found for charge_id: #{charge_id}"
  end
end

get '/success' do
  order_id = params[:order_id]
  order = Order.find_by(order_id: order_id)

  if order && order.status == 'paid'
    erb :success
  else
    erb :error
  end
end

get '/cancel' do
  order_id = params[:order_id]
  order = Order.find_by(order_id: order_id)

  if order
    erb :cancel
  else
    erb :error
  end
end

# Health check endpoint
get '/health' do
  content_type :json
  { status: 'healthy', timestamp: Time.now.to_s }.to_json
end
