require 'sinatra'
require 'httparty'
require 'json'

# PrivatBank API endpoint
PRIVATBANK_API_URL = 'https://api.privatbank.ua/p24api/exchange_rates?json&date='

# Fetch exchange rates from PrivatBank API
def fetch_exchange_rates
  begin
    # Get current date in format DD.MM.YYYY
    current_date = Time.now.strftime('%d.%m.%Y')

    # Make API request
    response = HTTParty.get("#{PRIVATBANK_API_URL}#{current_date}")

    if response.success?
      JSON.parse(response.body)
    else
      { error: "Failed to fetch data: #{response.code}" }
    end
  rescue => e
    { error: "Exception occurred: #{e.message}" }
  end
end

# Extract relevant currency rates
def extract_rates(data)
  return [] if data['exchangeRates'].nil?

  # Filter only USD and EUR rates (you can add more currencies as needed)
  rates = data['exchangeRates'].select do |rate|
    rate['currency'] == 'USD' || rate['currency'] == 'EUR'
  end

  rates.map do |rate|
    {
      currency: rate['currency'],
      buy: rate['buy'],
      sell: rate['sell']
    }
  end
end

# Main route
get '/' do
  @exchange_data = fetch_exchange_rates
  @rates = extract_rates(@exchange_data)
  @date = Time.now.strftime('%d.%m.%Y')

  erb :index
end

# API endpoint for JSON data
get '/api/rates' do
  content_type :json
  fetch_exchange_rates.to_json
end
