require 'sinatra'
require 'httparty'
require 'json'
require 'geocoder'
require 'addressable/uri'

# Configure Geocoder
Geocoder.configure(
  timeout: 10,
  units: :km
)

# Nova Poshta API configuration
NOVA_POSHTA_API_URL = "https://api.novaposhta.ua/v2.0/json/"
NOVA_POSHTA_API_KEY = ENV['NOVA_POSHTA_API_KEY'] || 'YOUR_API_KEY_HERE'

# Helper method to get locker locations
def get_lockers_near_address(address)
  # First geocode the address to get coordinates
  results = Geocoder.search(address)

  return nil if results.empty?

  location = results.first
  lat = location.latitude
  lng = location.longitude

  # Get Nova Poshta offices (lockers)
  offices = get_nova_poshta_offices

  # Filter lockers within reasonable distance (50km)
  nearby_lockers = offices.select do |office|
    office_coords = [office[:latitude], office[:longitude]]
    distance = Geocoder::Calculations.distance_between(
      [lat, lng], 
      office_coords
    )
    distance <= 50
  end

  # Sort by distance
  nearby_lockers.sort_by! do |office|
    Geocoder::Calculations.distance_between(
      [lat, lng], 
      [office[:latitude], office[:longitude]]
    )
  end

  nearby_lockers.first(20) # Return top 20 closest
end

