```ruby
# app.rb
require 'sinatra'
require 'twilio-ruby'
require 'bcrypt'
require 'dotenv/load'
require 'json'

# Load environment variables
set :twilio_account_sid, ENV['TWILIO_ACCOUNT_SID']
set :twilio_auth_token, ENV['TWILIO_AUTH_TOKEN']
set :twilio_phone_number, ENV['TWILIO_PHONE_NUMBER']

# Initialize Twilio client
def twilio_client
  @twilio_client ||= Twilio::REST::Client.new(
    settings.twilio_account_sid,
    settings.twilio_auth_token
  )
end

# In-memory storage for verification codes (use database in production)
VERIFICATION_CODES = {}

# Generate a 6-digit verification code
def generate_verification_code
  rand(100000..999999).to_s
end

# Send SMS verification code
def send_verification_sms(phone_number)
  code = generate_verification_code
  VERIFICATION_CODES[phone_number] = {
    code: code,
    created_at: Time.now
  }

  begin
    twilio_client.messages.create(
      from: settings.twilio_phone_number,
      to: phone_number,
      body: "Your verification code is: #{code}"
    )
    true
  rescue => e
    puts "Failed to send SMS: #{e.message}"
    false
  end
end

# Verify the code entered by the user
def verify_code(phone_number, entered_code)
  stored = VERIFICATION_CODES[phone_number]

  return false unless stored

  # Check if code is expired (5 minutes)
  if Time.now - stored[:created_at] > 300
    VERIFICATION_CODES.delete(phone_number)
    return false
  end

  # Check if code matches
  if BCrypt::Password.new(stored[:code]) == entered_code
    VERIFICATION_CODES.delete(phone_number)
    return true
  else
    return false
  end
end

# Routes

# Home page
get '/' do
  erb :index
end

# Send verification code
post '/send_verification' do
  phone_number = params[:phone_number]

  if phone_number.nil? || phone_number.empty?
    return { error: 'Phone number is required' }.to_json
  end

  # Simple phone number validation (you might want to use a more robust validation)
  if phone_number.length < 10
    return { error: 'Invalid phone number' }.to_json
  end

  if send_verification_sms(phone_number)
    { success: true, message: 'Verification code sent!' }.to_json
  else
    { error: 'Failed to send verification code' }.to_json
  end
end

# Verify code
post '/verify_code' do
  phone_number = params[:phone_number]
  entered_code = params[:code]

  if phone_number.nil? || entered_code.nil?
    return { error: 'Phone number and code are required' }.to_json
  end

  if verify_code(phone_number, entered_code)
    { success: true, message: 'Verification successful!' }.to_json
  else
    { error: 'Invalid or expired verification code' }.to_json
  end
end

