                if (data.error) {
                    showMessage(data.error, true);
                } else {
                    showMessage(data.message);
                    document.getElementById('send-section').classList.add('hidden');
                    document.getElementById('verify-section').classList.remove('hidden');
                }
            })
            .catch(error => {
                showMessage('Network error occurred', true);
                console.error('Error:', error);
            });
        }

        function verifyCode() {
            const phoneNumber = document.getElementById('phone_number').value;
            const code = document.getElementById('code').value;

            if (!phoneNumber || !code) {
                showMessage('Please enter both phone number and code', true);
                return;
            }

            fetch('/verify_code', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    phone_number: phoneNumber,
                    code: code 
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.error) {
                    showMessage(data.error, true);
                } else {
                    showMessage(data.message);
                    // Reset form after successful verification
                    document.getElementById('send-section').classList.remove('hidden');
                    document.getElementById('verify-section').classList.add('hidden');
                    document.getElementById('phone_number').value = '';
                    document.getElementById('code').value = '';
                }
            })
            .catch(error => {
                showMessage('Network error occurred', true);
                console.error('Error:', error);
            });
        }

        // Allow Enter key to submit forms
        document.getElementById('phone_number').addEventListener('keypress', function(e) {
