## Implementation

```ruby
# app.rb
require 'bundler/setup'
require 'treat'
require 'json'
require 'sinatra'

# Initialize Treat for language detection
Treat::Language::Detector.load!

# Helper method to detect language
def detect_language(text)
  return 'unknown' if text.nil? || text.strip.empty?

  # Use Treat's language detector
  detector = Treat::Language::Detector.new
  result = detector.detect(text)

  # Return the detected language code or unknown
  result.language_code || 'unknown'
rescue => e
  puts "Error detecting language: #{e.message}"
  'unknown'
end

# Helper method to get language name from code
def language_name(code)
  case code
  when 'en' then 'English'
  when 'es' then 'Spanish'
  when 'fr' then 'French'
  when 'de' then 'German'
  when 'it' then 'Italian'
  when 'pt' then 'Portuguese'
  when 'ru' then 'Russian'
  when 'ja' then 'Japanese'
  when 'ko' then 'Korean'
  when 'zh' then 'Chinese'
  when 'ar' then 'Arabic'
  when 'hi' then 'Hindi'
  else 'Unknown'
  end
end

# Routes
get '/' do
  erb :index
end

post '/detect' do
  content_type :json

  begin
    # Parse JSON from request
    data = JSON.parse(request.body.read)
    comment = data['comment']

    # Detect language
    language_code = detect_language(comment)
    language_name = language_name(language_code)

    # Return result
    {
      comment: comment,
      language_code: language_code,
      language_name: language_name,
      confidence: 0.9 # Simplified confidence
    }.to_json

  rescue JSON::ParserError
    status 400
    { error: 'Invalid JSON' }.to_json
  rescue => e
    status 500
    { error: 'Internal server error' }.to_json
  end
end

# For testing directly
