  # Validate phone number format
  if phone_number.nil? || phone_number.strip.length < 10
    return json_response({ error: 'Invalid phone number' }, 400)
  end

  # Generate verification code
  code = generate_verification_code
  expires_at = Time.now.to_i + 300 # 5 minutes expiry

  # Store in database
  begin
    DB.execute(
      "INSERT OR REPLACE INTO users (phone_number, verification_code, code_expires_at) 
       VALUES (?, ?, ?)",
      [phone_number, code, expires_at]
    )

    # Send SMS
    message = "Your verification code is: #{code}. This code expires in 5 minutes."
    if send_sms(phone_number, message)
      json_response({ message: 'Verification code sent successfully', phone_number: phone_number })
    else
      json_response({ error: 'Failed to send verification code' }, 500)
    end
  rescue => e
