# Verify code
post '/verify_code' do
  phone_number = params[:phone_number]
  entered_code = params[:verification_code]

  # Validate input
  if phone_number.nil? || entered_code.nil?
    return json_response({ error: 'Phone number and code are required' }, 400)
  end

  # Check if user exists in database
  result = DB.execute(
    "SELECT verification_code, code_expires_at FROM users WHERE phone_number = ?",
    [phone_number]
  ).first

  if result.nil?
    return json_response({ error: 'No verification attempt found for this number' }, 404)
  end

  stored_code = result['verification_code']
  expires_at = result['code_expires_at'].to_i

  # Check if code is expired
  if code_expired?(expires_at)
    # Clean up expired code
    DB.execute("DELETE FROM users WHERE phone_number = ?", [phone_number])
    return json_response({ error: 'Verification code has expired' }, 400)
  end

  # Verify code
  if entered_code == stored_code
    # Mark user as verified
    DB.execute(
      "UPDATE users SET verified = TRUE WHERE phone_number = ?",
      [phone_number]
    )

    json_response({ 
