```ruby
require 'sinatra'
require 'twilio-ruby'
require 'sqlite3'
require 'bcrypt'
require 'dotenv/load'

# Initialize database
def initialize_database
  db = SQLite3::Database.new('verification.db')
  db.execute <<-SQL
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      phone_number TEXT UNIQUE,
      verification_code TEXT,
      code_expires_at INTEGER,
      verified BOOLEAN DEFAULT FALSE
    );
  SQL
  db
end

# Initialize Twilio client
def twilio_client
  @twilio_client ||= Twilio::REST::Client.new(
    ENV['TWILIO_ACCOUNT_SID'],
    ENV['TWILIO_AUTH_TOKEN']
  )
end

# Generate a 6-digit verification code
def generate_verification_code
  rand(100000..999999).to_s
end

# Send SMS verification code
def send_verification_sms(phone_number, code)
  begin
    twilio_client.messages.create(
      from: ENV['TWILIO_PHONE_NUMBER'],
      to: phone_number,
      body: "Your verification code is: #{code}"
    )
    true
  rescue => e
    puts "Failed to send SMS: #{e.message}"
    false
  end
end

# Store user in database
def store_user(phone_number)
  db = initialize_database
  db.execute(
    "INSERT OR REPLACE INTO users (phone_number, verification_code, code_expires_at) VALUES (?, ?, ?)",
    phone_number, nil, nil
  )
  db.close
end

# Get user from database
def get_user(phone_number)
  db = initialize_database
  result = db.execute("SELECT * FROM users WHERE phone_number = ?", phone_number)
  db.close
  result.first
end

# Update user with verification code
def update_user_verification_code(phone_number, code)
  db = initialize_database
  expires_at = Time.now.to_i + 300 # 5 minutes from now
  db.execute(
    "UPDATE users SET verification_code = ?, code_expires_at = ? WHERE phone_number = ?",
    code, expires_at, phone_number
  )
  db.close
end

# Verify code
def verify_code(phone_number, entered_code)
  db = initialize_database
  user = get_user(phone_number)

  if user.nil?
    db.close
    return { valid: false, error: "User not found" }
  end

  if user[3].nil? || user[4].nil?
    db.close
    return { valid: false, error: "No verification code generated" }
  end

  # Check if code expired
  if Time.now.to_i > user[4]
    db.execute("UPDATE users SET verification_code = NULL, code_expires_at = NULL WHERE phone_number = ?", phone_number)
    db.close
    return { valid: false, error: "Verification code has expired" }
  end

  # Check if code matches
  if user[3] == entered_code
    db.execute("UPDATE users SET verified = TRUE, verification_code = NULL, code_expires_at = NULL WHERE phone_number = ?", phone_number)
    db.close
    return { valid: true, error: nil }
  else
    db.close
    return { valid: false, error: "Invalid verification code" }
  end
end

# Routes

get '/' do
  erb :index
end

post '/send-code' do
  phone_number = params[:phone_number]

  if phone_number.nil? || phone_number.empty?
    return { error: "Phone number is required" }.to_json
  end

  # Store user
  store_user(phone_number)

  # Generate and send verification code
  code = generate_verification_code
  success = send_verification_sms(phone_number, code)

  if success
    update_user_verification_code(phone_number, code)
    { status: "success", message: "Verification code sent" }.to_json
  else
    { status: "error", message: "Failed to send verification code" }.to_json
  end
end

post '/verify-code' do
  phone_number = params[:phone_number]
  entered_code = params[:code]

  if phone_number.nil? || entered_code.nil?
    return { error: "Phone number and code are required" }.to_json
  end

  result = verify_code(phone_number, entered_code)

  if result[:valid]
    { status: "success", message: "Verification successful" }.to_json
  else
    { status: "error", message: result[:error] }.to_json
  end
end

# For demonstration purposes - view all users (remove in production)
get '/users' do
  db = initialize_database
  users = db.execute("SELECT * FROM users")
  db.close
  users.to_json
end
