# Payment return handler
get '/payment/return' do
  # This endpoint is called by PrivatBank after payment completion
  payment_id = params[:payment_id]
  transaction_id = params[:transaction_id]

  status = params[:status] || 'completed'

  # Update payment status
  payment = Payment.find_by(payment_id: payment_id)
  if payment
    payment.update(status: status, transaction_id: transaction_id)

    # Update order status
    order = payment.order
    order.update(status: status == 'completed' ? 'paid' : 'failed')

    erb :payment_return, locals: {
      success: status == 'completed',
      message: status == 'completed' ? 'Payment successful!' : 'Payment failed.',
      payment_id: payment_id
    }
  else
    erb :payment_return, locals: {
      success: false,
      message: 'Payment not found.',
      payment_id: payment_id
    }
  end
end

# Payment cancel handler
get '/payment/cancel' do
  # This endpoint is called when user cancels payment
  payment_id = params[:payment_id]

  payment = Payment.find_by(payment_id: payment_id)
  if payment
    payment.update(status: 'cancelled')
    order = payment.order
    order.update(status: 'cancelled')
  end

  erb :payment_cancel, locals: {
    payment_id: payment_id
  }
end

# Get order status
get '/order/:id' do
  content_type :json

  order = Order.find_by(id: params[:id])
  if order
    payment = Payment.find_by(order_id: order.id)
    json({
      order_id: order.id,
      amount: order.amount,
      status: order.status,
      payment_status: payment ? payment.status : 'no_payment',
      created_at: order.created_at
    })
  else
    status 404
    json({ error: 'Order not found' })
  end
end

# Admin section
get '/admin' do
  @orders = Order.all.order(created_at: :desc)
  erb :admin
end

# Initialize database tables
before do
  ActiveRecord::Schema.define do
    unless table_exists?(:orders)
      create_table :orders do |t|
        t.decimal :amount, precision: 10, scale: 2
        t.string :customer_name
        t.string :customer_email
        t.integer :installment_months
        t.string :status
        t.timestamps
      end
    end

    unless table_exists?(:payments)
      create_table :payments do |t|
        t.references :order, null: false, foreign_key: true
        t.decimal :amount, precision: 10, scale: 2
        t.string :payment_id
        t.string :status
        t.string :transaction_id
        t.string :payment_method
        t.timestamps
      end
    end
  end
end
