# Ruby Implementation for SEPA Credit Transfer XML (pain.001) Generation

First, let's create the Gemfile with the required dependencies:

```ruby
# Gemfile
source 'https://rubygems.org'

gem 'builder'
gem 'activesupport' # For date/time formatting
gem 'sepa' # Optional - provides SEPA-specific helpers
```

Now, here's the implementation to generate a SEPA credit transfer XML file (pain.001.001.03):

```ruby
# sepa_payment_generator.rb
require 'builder'
require 'date'
require 'active_support/core_ext'

class SepaPaymentGenerator
  attr_reader :xml

  # Initialize with payment details
  def initialize(
    payment_information_id: "PMT#{Date.today.strftime('%Y%m%d%H%M%S')}",
    payment_method: "TRF",
    batch_booking: true,
    charge_bearer: "SLEV",
    currency: "EUR",
    debtor: {
      name: "Your Company Name",
      account: "DE89370400440532013000",
      bic: "COBADEFFXXX"
    },
    payments: []
  )
    @payment_information_id = payment_information_id
    @payment_method = payment_method
    @batch_booking = batch_booking
    @charge_bearer = charge_bearer
    @currency = currency
    @debtor = debtor
    @payments = payments
  end

  # Generate the XML
  def generate
    @builder = Builder::XmlMarkup.new(indent: 2)
    @builder.instruct! :xml, version: "1.0", encoding: "UTF-8"

    @builder.Document do
      @builder.CstmrCdtTrfInitn do
        generate_payment_information
        generate_payments
      end
    end

    @xml = @builder.target!
  end

  private

  def generate_payment_information
    @builder.PmtInf do
      @builder.PmtInfId(@payment_information_id)
      @builder.PmtMtd(@payment_method)
      @builder.BtchBookg(@batch_booking ? "true" : "false")
      @builder.NbOfTxs(@payments.size.to_s)
      @builder.CtgyPurp do
        @builder.CdOrPrtry do
          @builder.Cd("CASH")
        end
      end
      @builder.ReqdExctnDt(Date.today.strftime("%Y-%m-%d"))
      @builder.Dbtr do
        @builder.Nm(@debtor[:name])
        generate_account_identification(:DbtrAcct, @debtor[:account])
        @builder.CdtTrfTxInf do
          @builder.InstdAmt(@debtor[:amount], currency: @currency)
        end
      end
      @builder.CdtrAgt do
        @builder.FIID do
          @builder.FinInstnId do
            @builder.BICFI(@debtor[:bic])
          end
        end
      end
      @builder.ChrgBr(@charge_bearer)
      @builder.InstdAmt(@total_amount.to_s, currency: @currency)
    end
  end

  def generate_payments
    @payments.each do |payment|
      @builder.CdtTrfTxInf do
        @builder.PmtId do
          @builder.InstgAgt do
            @builder.FIID do
              @builder.FinInstnId do
                @builder.BICFI(payment[:creditor_bic])
              end
            end
          end
        end
        @builder.InstdAmt(payment[:amount].to_s, currency: @currency)
        @builder.ChrgBr(payment[:charge_bearer] || @charge_bearer)
        @builder.Dbtr do
          @builder.Nm(payment[:debtor_name] || @debtor[:name])
        end
        @builder.Cdtr do
          @builder.Nm(payment[:creditor_name])
          generate_account_identification(:CdtrAcct, payment[:creditor_account])
        end
        @builder.RmtInf do
          @builder.Ustrd(payment[:reference] || "Payment reference")
        end
        @builder.Purp do
          @builder.CdOrPrtry do
            @builder.Cd("SALA")
          end
        end
      end
    end
  end

  def generate_account_identification(tag, account)
    @builder.send(tag) do
      @builder.IBAN(account) if account.is_a?(String) && account.length.between?(10, 34)
      # Add support for other account types if needed
    end
  end

  def total_amount
    @total_amount ||= @payments.sum { |p| p[:amount].to_f }
  end
end

# Example Usage
if __FILE__ == $0
  payments = [
    {
      creditor_name: "Supplier 1",
      creditor_account: "DE89370400440532013001",
      creditor_bic: "COBADEFFXXX",
      amount: 1500.00,
      reference: "Invoice 12345"
    },
    {
      creditor_name: "Supplier 2",
      creditor_account: "DE89370400440532013002",
      creditor_bic: "COBADEFFXXX",
      amount: 2750.00,
      reference: "Invoice 67890"
    }
  ]

  generator = SepaPaymentGenerator.new(
    payment_information_id: "PMT20231201120000",
    debtor: {
      name: "Your Company",
      account: "DE89370400440532013000",
      bic: "COBADEFFXXX"
    },
    payments: payments
  )

  generator.generate
  puts generator.xml

  # To save to a file:
  File.write("sepa_payment.xml", generator.xml)
end
```

