## Налаштування WebAuthn у Rails

### 1. Встановлення та конфігурація

```ruby
# config/initializers/webauthn.rb
Rails.application.configure do
  config.webauthn = {
    # Домен вашого застосунку
    rp: {
      name: "Ваш застосунок",
      id: "example.com" # Довжина 128 символів або менше
    },
    # Опції для WebAuthn
    allow_credentials: {
      # Ви можете налаштувати які ключі дозволені
    },
    # Опції для аутентифікації
    attestation_conveyance_preference: "none",
    authenticator_selection: {
      require_resident_key: false,
      user_verification: "preferred"
    },
    timeout: 60000
  }
end
```

### 2. Модель користувача

```ruby
# app/models/user.rb
class User < ApplicationRecord
  has_many :credentials, class_name: 'Webauthn::Credential'
  accepts_nested_attributes_for :credentials

  # Методи для WebAuthn
  def webauthn_credentials
    credentials.map do |credential|
      {
        id: credential.external_id,
        type: credential.credential_type,
        transports: credential.transports
      }
    end
  end
end
```

### 3. Контролер для реєстрації нового ключа

```ruby
# app/controllers/credentials_controller.rb
class CredentialsController < ApplicationController
  before_action :authenticate_user!

  def create
    # Створюємо виклик WebAuthn
    options = Webauthn::AuthenticatorSelection.new(
      require_resident_key: true,
      user_verification: "preferred"
    )

    challenge = Webauthn::GenerateChallenge.call(
      user: current_user,
      options: options
    )

    # Зберігаємо виклик для пізнішого використання
    session[:webauthn_challenge] = challenge.challenge

    # Відповідь у JSON форматі
    respond_to do |format|
      format.json { render json: challenge }
    end
  end

  def verify
    # Отримуємо виклик з сесії
    challenge = session.delete(:webauthn_challenge)

    credentials = current_user.webauthn_credentials

    result = Webauthn::VerifyAttestation.call(
      attestation: params[:attestation],
      challenge: challenge,
      credentials: credentials
    )

    if result.success?
      # Зберігаємо новий ключ
      credential = current_user.credentials.build(
        external_id: result.credential_id,
        credential_type: result.credential_type,
        transports: result.transports
      )

      if credential.save
        render json: { success: true, message: "Ключ успішно зареєстрований" }
      else
        render json: { success: false, message: "Не вдалося зберегти ключ" }, status: :unprocessable_entity
      end
    else
      render json: { success: false, message: result.message }, status: :unprocessable_entity
    end
  end
end
```

### 4. Контролер для аутентифікації

```ruby
# app/controllers/sessions_controller.rb
class SessionsController < ApplicationController
  def new
    # Видаємо виклик для аутентифікації
    challenge = Webauthn::GenerateChallenge.call(
      user: current_user,
      options: Webauthn::AuthenticatorSelection.new(
        user_verification: "preferred"
      )
    )

    session[:webauthn_challenge] = challenge.challenge
    respond_to do |format|
      format.json { render json: challenge }
    end
  end

  def verify
    # Отримуємо виклик з сесії
    challenge = session.delete(:webauthn_challenge)

    result = Webauthn::VerifyAuthentication.call(
      assertion: params[:assertion],
      challenge: challenge,
      credentials: current_user.webauthn_credentials
    )

    if result.success?
      # Успішна аутентифікація
      sign_in(current_user)
      render json: { success: true, message: "Аутентифікація успішна" }
    else
      # Помилка аутентифікації
      render json: { success: false, message: result.message }, status: :unprocessable_entity
    end
  end
end
```

