// app/javascript/webauthn.js
class WebAuthn {
  constructor() {
    this.publicKey = {
      challenge: '',
      rp: {
        name: '',
        id: ''
      },
      user: {
        id: '',
        name: '',
        displayName: ''
      },
      pubKeyCredParams: [{ type: 'public-key', alg: -7 }],
      authenticatorSelection: {
        authenticatorAttachment: 'cross-platform',
        requireResidentKey: true,
        userVerification: 'preferred'
      },
      timeout: 60000,
      attestation: 'none'
    };
  }

  async register() {
    try {
      // Отримуємо виклик від серверу
      const response = await fetch('/credentials', {
        method: 'POST',
        credentials: 'include'
      });

      const data = await response.json();

      this.publicKey.challenge = data.challenge;
      this.publicKey.rp = data.rp;
      this.publicKey.user = data.user;

      // Викликаємо WebAuthn API
      const credential = await navigator.credentials.create({
        publicKey: this.publicKey
      });

      // Відправляємо атенстацію на сервер для перевірки
      const verifyResponse = await fetch('/credentials/verify', {
        method: 'POST',
        body: JSON.stringify({ attestation: credential }),
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        credentials: 'include'
      });

      return await verifyResponse.json();
    } catch (error) {
      console.error('Помилка реєстрації:', error);
      return { success: false, message: error.message };
    }
  }

  async signIn() {
    try {
      // Отримуємо виклик від серверу
      const response = await fetch('/webauthn', {
        method: 'GET',
        credentials: 'include'
      });

      const data = await response.json();

      this.publicKey.challenge = data.challenge;

      // Викликаємо WebAuthn API
      const credential = await navigator.credentials.get({
        publicKey: this.publicKey
      });

      // Відправляємо атенстацію на сервер для перевірки
      const verifyResponse = await fetch('/webauthn/verify', {
        method: 'POST',
        body: JSON.stringify({ assertion: credential }),
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        credentials: 'include'
      });

      return await verifyResponse.json();
    } catch (error) {
      console.error('Помилка входу:', error);
      return { success: false, message: error.message };
    }
  }
}
```

## Додаткові примітки

1. Ви повинні налаштувати CORS у своєму застосунку, щоб дозволити запити з frontend.
2. Для виробничого використання рекомендується використовувати HTTPS.
3. Ви можете розширювати цю реалізацію, додаючи більше опцій WebAuthn.
4. Для тестування можна використовувати WebAuthn.ee або інші сервіси для тестування WebAuthn.

Цей код надає базову реалізацію WebAuthn (passkeys) у Rails застосунку. Ви можете адаптувати його під свої потреби та додати додаткові функції залежно від вимог вашого проекту.

# Ruby Implementation for WebAuthn Passkey Login in Rails

Here's a complete implementation for adding WebAuthn passkey login to a Rails application. I'll start with the Gemfile, then provide the implementation.

