end
```

### 5. Create WebAuthn Controller

```ruby
# app/controllers/webauthn_controller.rb
class WebauthnController < ApplicationController
  skip_before_action :verify_authenticity_token, only: [:assertion]

  def registration
    if current_user
      redirect_to root_path, notice: "You are already logged in"
    else
      @user = User.new
      @webauthn_credential = WebauthnCredential.new
    end
  end

  def create_credential
    @user = User.new(user_params)
    if @user.save
      challenge = Webauthn::Register.begin(
        user: @user,
        user_name: @user.email,
        display_name: @user.email,
        credential_ids: @user.credential_ids
      )

      render json: {
        challenge: challenge.challenge,
        user: {
          id: @user.id,
          name: @user.email,
          display_name: @user.email
        },
        rp: {
          name: Webauthn.config.rp_name,
          icon: Webauthn.config.rp_icon
        },
        pub_key_cred_params: [
          {
            type: "public-key",
            alg: -7, # ES256
            token_binding: {
              status: "unsupported"
            }
          }
        ],
        authenticator_selection: {
          require_resident_key: true,
          user_verification: "preferred"
        },
        attestation: "none" # For production
      }
    else
      redirect_to registration_path, alert: "Registration failed"
    end
  end

  def finish_registration
    registration_response = Webauthn::Register.finish(
      registration_response: registration_params,
      expected_challenge: params[:challenge],
      expected_origin: request.origin,
      expected_rp_id: request.domain,
      user: User.find(params[:user_id])
    )

    if registration_response.codename == :verification_failed
      render json: { error: "Verification failed" }, status: :unprocessable_entity
    else
      credential = registration_response.credential
      WebauthnCredential.create!(
        user: registration_response.user,
        credential_id: credential.credential_id,
        public_key: credential.public_key
      )

      sign_in_and_redirect(@user, event: :authentication)
    end
  end

  def assertion
    assertion_response = Webauthn::Assertion.finish(
      assertion_response: assertion_params,
      expected_challenge: params[:challenge],
      expected_origin: request.origin,
      expected_rp_id: request.domain,
      user: User.find_by(email: params[:email])
    )

    if assertion_response.codename == :verification_failed
      render json: { error: "Verification failed" }, status: :unprocessable_entity
    else
      user = assertion_response.user
      sign_in_and_redirect(user, event: :authentication)
    end
  end

  private

  def user_params
    params.require(:user).permit(:email, :password, :password_confirmation)
  end

  def registration_params
    params.require(:registration_response).permit(
      :id,
      :raw_id,
      :type,
      :response
    )
  end

  def assertion_params
    params.require(:assertion_response).permit(
      :id,
      :raw_id,
      :type,
      :response
    )
  end
end
```

