### 8. Add Authentication Challenge

Add this to your login form or a dedicated button:

```erb
<!-- app/views/layouts/application.html.erb -->
<a href="#" id="sign-in-with-passkey">Sign in with Passkey</a>

<script>
  document.getElementById('sign-in-with-passkey').addEventListener('click', async (e) => {
    e.preventDefault();

    const email = prompt("Enter your email:");
    if (!email) return;

    try {
      // Get the challenge
      const response = await fetch('/webauthn/assertion', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]').content
        },
        body: JSON.stringify({
          email: email
        })
      });

      const data = await response.json();

      if (response.ok) {
        // Start the assertion
        const credential = await navigator.credentials.get({
          publicKey: {
            challenge: Uint8Array.from(atob(data.challenge), c => c.charCodeAt(0)),
            rpId: data.rp_id,
            allowCredentials: data.allow_credentials.map(cred => ({
              id: Uint8Array.from(atob(cred.id), c => c.charCodeAt(0)),
              type: cred.type,
              transports: cred.transports
            })),
            userVerification: "preferred"
          }
        });

        // Finish the assertion
        const finishResponse = await fetch('/webauthn/assertion', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]').content
          },
          body: JSON.stringify({
            assertion_response: {
              id: credential.id,
              raw_id: arrayBufferToBase64(credential.rawId),
              type: credential.type,
              response: {
                authenticator_data: arrayBufferToBase64(credential.response.authenticatorData),
                client_data_json: arrayBufferToBase64(credential.response.clientDataJSON),
                signature: arrayBufferToBase64(credential.response.signature),
                user_handle: credential.response.userHandle ? arrayBufferToBase64(credential.response.userHandle) : null
              }
            },
            challenge: data.challenge,
            email: email
          })
        });

        if (finishResponse.ok) {
          window.location.href = '/';
        } else {
          alert('Sign in failed. Please try again.');
        }
      } else {
        alert('Failed to get challenge. Please try again.');
      }
    } catch (error) {
      alert(`Error during sign in: ${error.message}`);
    }
  });

  function arrayBufferToBase64(buffer) {
    return btoa(String.fromCharCode.apply(null, new Uint8Array(buffer)));
  }
</script>
