## 6. JavaScript код для клієнта

```javascript
// app/javascript/webpush.js
import { initializeApp } from "firebase/app";
import { getMessaging, onMessage, getToken } from "firebase/messaging";
import { WebPush } from 'firebase/messaging/sw';

const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID",
  measurementId: "YOUR_MEASUREMENT_ID"
};

const app = initializeApp(firebaseConfig);
const messaging = getMessaging(app);

// Запитуємо дозвіл на сповіщення
function requestPermission() {
  return Notification.requestPermission();
}

// Реєструємо сервіс-воркер
function registerServiceWorker() {
  return navigator.serviceWorker.register('/sw.js');
}

// Отримуємо токен для push-сповіщень
async function getTokenFromServer() {
  const token = await getToken(messaging, {
    vapidKey: 'YOUR_VAPID_PUBLIC_KEY',
  }).catch((err) => {
    console.error('Unable to get permission to notify.', err);
  });

  if (token) {
    // Відправляємо токен на сервер
    const response = await fetch('/webpush/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]').content
      },
      body: JSON.stringify({ subscription: token })
    });

    return response.json();
  }
}

// Слухаємо вхідні сповіщення
onMessage(messaging, (payload) => {
  console.log('Message received. ', payload);
  // Відображаємо сповіщення
  new Notification(payload.notification.title, {
    body: payload.notification.body,
  });
});

// Ініціалізація
async function initWebPush() {
  if ('serviceWorker' in navigator) {
    await registerServiceWorker();
    const permission = await requestPermission();
    if (permission === 'granted') {
      await getTokenFromServer();
    }
  }
}

initWebPush();
```

