**Підпис XML-документу за допомогою XMLDSig сертифікатом X.509 та перевірка підпису**
```ruby
require 'nokogiri'
require 'openssl'

# Визначте вміст XML-документу
xml = <<-XML
<?xml version="1.0" encoding="UTF-8"?>
<root>
  <element>Дані елемента</element>
</root>
XML

# Підпишіть XML-документ за допомогою сертифіката X.509
cert = OpenSSL::X509::Certificate.new(File.read('path/to/cert.pem'))
signature = OpenSSL::Digest::SHA1.new
digest = OpenSSL::Digest::SHA1.new
signed_xml = Nokogiri::XML::Builder.new do |xml|
  xml.root {
    xml.element('SignedInfo') {
      xml.Signature {
        xml.SignedInfo {
          xml.SignatureMethod { xml.MethodName = 'http://www.w3.org/2000/09/xmldsig#rsa-sha1' }
          xml.SignedInfo {
            xml.canonicalizationMethod { xml.Method = 'http://www.w3.org/2000/09/xmldsig#exclusive-c14n' }
          }
        }
        xml.SignatureValue { xml.Value = digest.hexdump }
      }
      xml.SignedInfo {
        xml.canonicalizationMethod { xml.Method = 'http://www.w3.org/2000/09/xmldsig#exclusive-c14n' }
      }
    }
  }
  xml.root {
    xml.SignedInfo {
      xml.Signature {
        xml.SignedInfo {
          xml.SignatureMethod { xml.MethodName = 'http://www.w3.org/2000/09/xmldsig#rsa-sha1' }
          xml.SignedInfo {
            xml.canonicalizationMethod { xml.Method = 'http://www.w3.org/2000/09/xmldsig#exclusive-c14n' }
          }
        }
      }
    }
  }
end

# Перевірте підпис
signed_xml = Nokogiri::XML(signed_xml.to_s)
signature = OpenSSL::Digest::SHA1.new
digest = OpenSSL::Digest::SHA1.new
signature.verify(digest.hexdump, signed_xml.at('/SignedInfo/Signature/SignatureValue').text)

puts "Підпис перевірено: #{signature.verify(digest.hexdump, signed_xml.at('/SignedInfo/Signature/SignatureValue').text) ? 'Так' : 'Ні'}"
```

